const {normalize}=require('./options.cjs');
const {matching}=require('./matching.cjs');
function search(records,options={}){const o=normalize(options);const items=matching(records.slice(o.page*o.limit,(o.page+1)*o.limit),o.query);return {items,total:items.length,page:o.page,pageCount:Math.ceil(records.length/o.limit),hasNext:items.length===o.limit};}
module.exports={search};

