const assert=require('node:assert/strict');
const {normalize}=require('./src/options.cjs');
const {matching}=require('./src/matching.cjs');
const {search}=require('./src/search.cjs');
assert.deepEqual(normalize({}),{query:'',page:1,limit:10});
assert.deepEqual(normalize({query:'  ALP  ',page:2,limit:1}),{query:'alp',page:2,limit:1});
for(const options of [{page:0},{page:-1},{page:1.5},{page:'1'},{page:null},{page:Infinity},{limit:0},{limit:101},{limit:1.5},{limit:'2'},{query:null},{query:2}]){
 assert.throws(()=>normalize(options),RangeError);
 assert.throws(()=>search([],options),RangeError);
}
const rows=Object.freeze([{id:3,name:'Alpine',createdAt:2},{id:4,name:'Beta',createdAt:0},{id:2,name:'ALPHA',createdAt:1},{id:1,name:'alphabet',createdAt:1}].map(Object.freeze));
assert.deepEqual(matching(rows,'alp').map(r=>r.id),[1,2,3]);
assert.deepEqual(rows.map(r=>r.id),[3,4,2,1]);
assert.deepEqual(search(rows,{query:' ALP ',page:1,limit:2}),{items:[rows[3],rows[2]],total:3,page:1,pageCount:2,hasNext:true});
assert.deepEqual(search(rows,{query:'alp',page:2,limit:2}),{items:[rows[0]],total:3,page:2,pageCount:2,hasNext:false});
assert.deepEqual(search(rows,{query:'alp',page:3,limit:2}),{items:[],total:3,page:3,pageCount:2,hasNext:false});
assert.deepEqual(search(rows,{query:'absent'}),{items:[],total:0,page:1,pageCount:0,hasNext:false});
assert.deepEqual(search([],{}),{items:[],total:0,page:1,pageCount:0,hasNext:false});
assert.equal(search(rows,{page:1,limit:4}).hasNext,false);
const options=Object.freeze({query:' ALP ',page:1,limit:2});search(rows,options);assert.equal(options.query,' ALP ');
console.log('protected pagination acceptance passed');
